const D = { scale: 1, n: 8, energy: .6, speed: 1, hue: 320, sway: .6, density: .5, x: .5, y: .58, style: 'papel-picado', act: 'parade', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const PI = Math.PI, TAU2 = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const N = Math.max(4, Math.min(14, Math.round(P.n)));
const sty = P.style;
const glow = (sty === 'xray' || sty === 'neon');
const inten = 0.4 + 0.6 * K.intensity;
const sec = ((Math.floor(K.section) % 8) + 8) % 8;

// festive papel-picado tissue palette (hue-shifted by P.hue)
const FEST = [ [0,0,0], [40,90,100], [190,80,96], [140,70,92], [55,88,100], [270,55,96] ];
const ho = P.hue - 320;

// act programs: how the line is arranged
const ACT = {
  parade:    { seg: 1.0, coil: 0.0, scatter: 0.0, sp: 1.0 },
  spiral:    { seg: 0.85, coil: 0.4 + 0.5 * (sec % 4) / 3, scatter: 0.0, sp: 0.85 },
  breakdown: { seg: 1.15, coil: 0.0, scatter: (sec % 4 === 2) ? 0.9 : 0.15, sp: 1.2 } };
const ac = ACT[P.act] || ACT.parade;

const seg = (0.9 / N + 0.02) * ac.seg;               // spacing along path (0..1 units)
const lead = K.t * 0.12 * P.speed * (0.6 + 0.8 * P.energy) * ac.sp;   // continuous scroll
const waveA = u * 0.11 * P.sway * (0.55 + 0.65 * inten);
const bodyH = u * 0.34 * P.scale;                    // skeleton height at scale 1

// ---- paint state helpers ----
let curW = 1;
function boneStroke(bright, a) {
  if (sty === 'neon') { stroke(hw(160 + ho), 90, 100, a == null ? 100 : a); }
  else if (sty === 'xray') { stroke(hw(200 + ho), 30, 100, a == null ? 90 : a); }
  else if (sty === 'engraving') { stroke(35, 12, 16, a == null ? 100 : a); }
  else stroke(0, 0, bright, a == null ? 100 : a);
}
function boneFill(col, a) {
  if (sty === 'neon') { noFill(); return false; }
  if (sty === 'xray') { fill(hw(200 + ho), 45, 96, (a == null ? 34 : a)); return true; }
  if (sty === 'engraving') { fill(38, 10, 90, a == null ? 100 : a); return true; }
  if (sty === 'bone') { fill(38, 16, 92, a == null ? 100 : a); return true; }
  fill(hw(col[0] + (col[1] ? ho : 0)), col[1], col[2], a == null ? 100 : a); return true; // papel-picado
}

// draw a single limb bone as a capsule
function bone(x1, y1, x2, y2, w, col) {
  const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) + 1e-3;
  const nx = -dy / len * w, ny = dx / len * w;
  if (sty === 'bone') { drawingContext.shadowBlur = 6; drawingContext.shadowColor = 'rgba(0,0,0,0.5)'; }
  const f = boneFill(col);
  if (glow) { boneStroke(100); strokeWeight(w * 1.1); line(x1, y1, x2, y2); }
  else {
    boneStroke(sty === 'engraving' ? 16 : 0, sty === 'papel-picado' ? 0 : 100);
    strokeWeight(sty === 'papel-picado' ? w * 0.16 : 1.1);
    if (!f) noStroke();
    beginShape();
    vertex(x1 + nx, y1 + ny); vertex(x2 + nx, y2 + ny);
    vertex(x2 - nx, y2 - ny); vertex(x1 - nx, y1 - ny);
    endShape(CLOSE);
    // knuckle ends
    if (f) { noStroke(); boneFill(col); ellipse(x1, y1, w * 2, w * 2); ellipse(x2, y2, w * 2, w * 2); }
  }
  if (sty === 'engraving') { // hatch shading
    boneStroke(16, 40); strokeWeight(0.6);
    for (let h = -1; h <= 1; h++) line(x1 + nx * h * 0.6, y1 + ny * h * 0.6, x2 + nx * h * 0.6, y2 + ny * h * 0.6);
  }
  drawingContext.shadowBlur = 0;
}

function skull(x, y, r, col, treble) {
  push(); translate(x, y);
  if (sty === 'bone') { drawingContext.shadowBlur = 8; drawingContext.shadowColor = 'rgba(0,0,0,0.5)'; }
  if (glow) {
    boneStroke(100); strokeWeight(r * 0.14); noFill();
    ellipse(0, -r * 0.1, r * 1.7, r * 1.9);
    rect(-r * 0.5, r * 0.55, r, r * 0.7, r * 0.2);
  } else {
    boneFill(col); if (sty === 'papel-picado') { noStroke(); } else { boneStroke(sty === 'engraving' ? 16 : 0); strokeWeight(1.1); }
    // scalloped cranium
    beginShape();
    for (let a = 0; a <= TAU2 + 0.01; a += TAU2 / 24) {
      const scal = (sty === 'papel-picado') ? (1 + 0.05 * Math.sin(a * 12)) : 1;
      vertex(Math.cos(a) * r * 0.85 * scal, -r * 0.1 + Math.sin(a) * r * 0.95 * scal);
    }
    endShape(CLOSE);
    boneFill(col); rect(-r * 0.5, r * 0.55, r, r * 0.62, r * 0.18);
  }
  drawingContext.shadowBlur = 0;
  // eye sockets + nasal (dark cut-outs)
  const eye = (sty === 'neon') ? null : (sty === 'xray') ? [200, 60, 20] : [0, 0, 6];
  if (eye) { noStroke(); fill(eye[0], eye[1], eye[2], sty === 'xray' ? 80 : 100); }
  else { noFill(); boneStroke(100); strokeWeight(r * 0.09); }
  const ew = r * 0.42;
  ellipse(-r * 0.34, -r * 0.16, ew, ew * 1.15);
  ellipse(r * 0.34, -r * 0.16, ew, ew * 1.15);
  if (eye) { fill(eye[0], eye[1], eye[2]); triangle(0, r * 0.05, -r * 0.14, r * 0.34, r * 0.14, r * 0.34); noStroke(); }
  else { triangle(0, r * 0.05, -r * 0.14, r * 0.34, r * 0.14, r * 0.34); }
  // grin teeth
  boneStroke(0, sty === 'neon' ? 90 : 70); strokeWeight(Math.max(0.8, r * 0.05));
  for (let t = -2; t <= 2; t++) line(t * r * 0.18, r * 0.55, t * r * 0.18, r * 0.95 + treble * r * 0.3);
  noStroke();
  pop();
}

// ---- draw the conga line ----
for (let i = N - 1; i >= 0; i--) {                    // back-to-front
  const col = FEST[(i + Math.floor(P.seed)) % FEST.length];
  const pos = lead - i * seg;
  const wrapT = ((pos % 1) + 1) % 1;                  // 0..1 wrap across width
  let bx = wrapT * (width + bodyH) - bodyH * 0.5;
  const phase = wrapT * TAU2 * 1.6 + K.t * 0.5 * P.speed;
  let by = height * P.y + Math.sin(phase) * waveA;
  // coil (spiral act) pulls line toward centre with rotation
  if (ac.coil > 0) { const cr = u * 0.28 * (1 - i / N); const ca = wrapT * TAU2 * 1.4 + K.t * 0.3;
    bx = bx * (1 - ac.coil) + (width * 0.5 + Math.cos(ca) * cr) * ac.coil;
    by = by * (1 - ac.coil) + (height * P.y + Math.sin(ca) * cr * 0.6) * ac.coil; }
  if (ac.scatter > 0) { bx += (fr(i * 2 + 1) - 0.5) * width * 0.5 * ac.scatter;
    by += (fr(i * 2 + 2) - 0.5) * height * 0.4 * ac.scatter; }

  // per-skeleton rippled kick (every 4th beat, cascading down the line)
  const local = K.beat * P.speed - i * 0.16;
  const lbi = Math.floor(local), lph = local - lbi;
  const onKick = ((((lbi % 4) + 4) % 4) === 0);
  const kick = onKick ? Math.pow(1 - lph, 3) : 0;
  const bob = -kick * bodyH * 0.09 + Math.sin(phase) * 0 - Math.abs(Math.sin(K.beat * PI * P.speed + i)) * bodyH * 0.02;
  by += bob;
  // treble rattle
  const rat = A.treble * u * 0.012 + K.pulse * u * 0.002;
  const jit = () => (fr(i * 9 + Math.floor(K.t * 30)) - 0.5) * rat;

  const s = bodyH;
  const w = s * 0.045;
  // slope tilt from wave
  const tilt = Math.cos(phase) * 0.12 * (waveA / (u * 0.11 + 1e-3));
  push();
  translate(bx + jit(), by + jit());
  rotate(tilt);
  // spine
  const hipY = 0, shoY = -s * 0.34, neckY = -s * 0.46;
  bone(0, hipY, 0, shoY, w * 0.9, col);
  // pelvis
  bone(-s * 0.11, hipY, s * 0.11, hipY, w * 1.1, col);
  // ribcage (curved bars)
  for (let r = 0; r < 4; r++) {
    const ry = shoY + r * s * 0.06;
    const rw = s * (0.13 - r * 0.012);
    boneFill(col, sty === 'xray' ? 22 : 100);
    if (sty === 'papel-picado') noStroke(); else { boneStroke(sty === 'engraving' ? 16 : 0); strokeWeight(1); if (glow) noFill(); }
    if (glow) { strokeWeight(w * 0.7); noFill(); }
    beginShape(); vertex(-rw, ry - s * 0.02); vertex(0, ry + s * 0.01); vertex(rw, ry - s * 0.02); endShape();
    // papel-picado punched holes in ribcage
    if (sty === 'papel-picado' && r % 2 === 0) { fill(0, 0, 8); ellipse(0, ry - s * 0.005, w * 1.1, w * 1.1); }
  }
  // arms reach forward onto shoulder ahead (conga hold) + swing on kick
  const armSw = kick * 0.5 + Math.sin(K.beat * PI * P.speed + i) * 0.15;
  const shx = s * 0.13;
  bone(-shx, shoY, -shx - s * 0.16, shoY - s * 0.02 - armSw * s * 0.1, w * 0.7, col);
  bone(-shx - s * 0.16, shoY - s * 0.02 - armSw * s * 0.1, -shx - s * 0.34, shoY - s * 0.12 - armSw * s * 0.16, w * 0.6, col);
  bone(shx, shoY, shx + s * 0.16, shoY + s * 0.04 + armSw * s * 0.08, w * 0.7, col);
  bone(shx + s * 0.16, shoY + s * 0.04 + armSw * s * 0.08, shx + s * 0.32, shoY - s * 0.02 - armSw * s * 0.12, w * 0.6, col);
  // legs — one plants, one kicks out on the beat (conga step)
  const kdir = (i % 2 === 0) ? 1 : -1;
  const kOut = kick * kdir * s * 0.24;
  const kUp = kick * s * 0.14;
  // planted leg
  bone(-s * 0.08, hipY, -s * 0.1, hipY + s * 0.26, w * 0.8, col);
  bone(-s * 0.1, hipY + s * 0.26, -s * 0.09, hipY + s * 0.5, w * 0.7, col);
  // kicking leg
  bone(s * 0.08, hipY, s * 0.11 + kOut * 0.5, hipY + s * 0.24 - kUp, w * 0.8, col);
  bone(s * 0.11 + kOut * 0.5, hipY + s * 0.24 - kUp, s * 0.12 + kOut, hipY + s * 0.46 - kUp * 1.4, w * 0.7, col);
  // skull
  skull(0, neckY - s * 0.14, s * 0.14, col, A.treble);
  pop();
}
noStroke();
drawingContext.shadowBlur = 0;
